//go:build arm64

package gf65536

// NEON kernels generated by go-asmgen (gen/galois_arm64_gen.go) into
// galois_arm64.s: VLD2/VST2 deinterleave and VTBL on the byte planes. NEON is
// the arm64 baseline, so there is no feature check.
func galMulNEON(dst, src []byte, tbl *[128]byte, n int)
func galMulAddNEON(dst, src []byte, tbl *[128]byte, n int)

func archTiers() []tier {
	return []tier{blockTier("neon", galMulNEON, galMulAddNEON)}
}
